package com.coolxer.model.dih.dashboard;

import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.annotation.JsonNaming;
import lombok.Data;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Server-compiled dashboard specification. The model may only supply this
 * structure; HTML, AMIS, API URLs and scripts are generated by the backend.
 */
@Data
@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
public class DashboardSpec {

    public static final String SCHEMA_VERSION = "1.0";
    public static final String MODE_HTML = "HTML_PAGE";
    public static final String MODE_LOW_CODE = "LOW_CODE_PAGE";
    public static final String THEME_DARK_TECH = "DARK_TECH";
    public static final List<String> TIME_PRESETS = List.of(
            "LAST_24_HOURS", "LAST_7_DAYS", "LAST_30_DAYS", "THIS_MONTH", "ALL_TIME");

    private String schemaVersion = SCHEMA_VERSION;
    private String dashboardId;
    private String name;
    private String description;
    private String mode = MODE_HTML;
    private String theme = THEME_DARK_TECH;
    private Integer refreshIntervalSeconds = 60;
    private String timeField;
    private String defaultTimeRange = "LAST_7_DAYS";
    private List<String> allowedTimeRanges = new ArrayList<>(TIME_PRESETS);
    private DashboardLayout layout = new DashboardLayout();
    private List<DashboardBlock> blocks = new ArrayList<>();

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardLayout {
        private Integer columns = 12;
        private List<DashboardRow> rows = new ArrayList<>();
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardRow {
        private String rowId;
        private List<DashboardLayoutItem> blocks = new ArrayList<>();
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardLayoutItem {
        private String blockId;
        private Integer span = 12;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardBlock {
        private String blockId;
        private String type;
        private String title;
        private String description;
        private DashboardQuery query;
        private List<DashboardMetricCard> metricCards = new ArrayList<>();
        private DashboardRecords records;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardQuery {
        private String tool;
        private String entity;
        private Map<String, Object> request = new LinkedHashMap<>();
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardMetricCard {
        private String label;
        private String field;
        private String prefix;
        private String suffix;
        private Integer precision;
    }

    /** Read-only record table. Mutation flags are intentionally not part of the model. */
    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardRecords {
        private String entity;
        private List<DashboardRecordColumn> columns = new ArrayList<>();
        private List<DashboardRecordFilter> filters = new ArrayList<>();
        private String defaultSortField;
        private String defaultSortDirection = "desc";
        private Integer pageSize = 12;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardRecordColumn {
        private String field;
        private String label;
        private Boolean sortable = true;
        private Integer width;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DashboardRecordFilter {
        private String field;
        private String label;
        private String operator = "equal";
        private String inputType;
    }
}
